const upsertPreview = `-- name: UpsertPreview :one

INSERT INTO previews (application_id, provider, pr_id, source_branch, head_sha, is_fork, repo_reference)
VALUES ($1, $2, $3, $5, $6, $4, $7)
ON CONFLICT (application_id, provider, pr_id) DO UPDATE SET
    source_branch = excluded.source_branch,
    head_sha = excluded.head_sha,
    is_fork = excluded.is_fork,
    repo_reference = COALESCE(excluded.repo_reference, previews.repo_reference),
    status = CASE WHEN previews.status IN ('destroyed', 'failed') THEN 'queued'::preview_status ELSE previews.status END,
    -- Reviving a DESTROYED preview is a fresh start under the manual-first
    -- policy: a reopened PR behaves like an opened one — reservation only,
    -- the old deploy order does not carry over. A failed preview keeps it
    -- (the attempt engaged it; pushes may retry).
    deploy_requested_at = CASE WHEN previews.status = 'destroyed' THEN NULL ELSE previews.deploy_requested_at END,
    destroyed_at = NULL,
    updated_at = now()
RETURNING id, uuid, application_id, provider, pr_id, source_branch, head_sha, is_fork, fork_approved_by, fork_approved_at, fqdn, status, cleanup_error, last_deployed_at, last_activity_at, destroyed_at, created_at, updated_at, repo_reference, expiry_warned_at, random_slug, deploy_requested_at
`

type UpsertPreviewParams struct {
	ApplicationID int64
	Provider      GitProvider
	PrID          int32
	IsFork        bool
	SourceBranch  *string
	HeadSha       *string
	RepoReference *string
}

// PR previews (data-dictionary §8.9, §20.4).
// New commit on the same PR reuses the identity — the instance redeploys,
// it is never duplicated (§20.4). A destroyed preview row is revived when
// the PR reopens.
func (q *Queries) UpsertPreview(ctx context.Context, arg UpsertPreviewParams) (Preview, error) {
	row := q.db.QueryRow(ctx, upsertPreview,
		arg.ApplicationID,
		arg.Provider,
		arg.PrID,
		arg.IsFork,
		arg.SourceBranch,
		arg.HeadSha,
		arg.RepoReference,
	)
	var i Preview
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.ApplicationID,
		&i.Provider,
		&i.PrID,
		&i.SourceBranch,
		&i.HeadSha,
		&i.IsFork,
		&i.ForkApprovedBy,
		&i.ForkApprovedAt,
		&i.Fqdn,
		&i.Status,
		&i.CleanupError,
		&i.LastDeployedAt,
		&i.LastActivityAt,
		&i.DestroyedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RepoReference,
		&i.ExpiryWarnedAt,
		&i.RandomSlug,
		&i.DeployRequestedAt,
	)
	return i, err
}
